    return kernel(inputs=[x,w],template=[('T',x.dtype),('BK',bk),('NT',nt)],grid=(N//nt*128,M//16,1),
        threadgroup=(128,1,1),output_shapes=[(*x.shape[:-1],N)],output_dtypes=[x.dtype])[0]
